// a free one.
pub builtin type UdpSocket {
  // Sends to "host:port".
  fn send_to(self, data: Bytes, address: String) throws
  // Waits for the next datagram.
  fn receive(self) throws -> Datagram
  // The local port.
  fn port(self) -> Int
  fn close(self) throws
}

pub fn udp(port: Int) throws -> UdpSocket
